import{az as e,P as a,Q as r,aQ as d}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const m=JSON.parse('{"title":"渲染机制","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/渲染机制.md","filePath":"框架/react/react/渲染机制.md","lastUpdated":1785246304000}'),i={name:"框架/react/react/渲染机制.md"};function o(l,t,n,c,s,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="渲染机制" tabindex="-1">渲染机制 <a class="header-anchor" href="#渲染机制" aria-label="Permalink to “渲染机制”">​</a></h1><p>React 渲染可以概括为：状态变化 → 算出新 UI 描述 → 尽量少地更新真实 DOM。</p><p>理解这条链路，是读懂并发渲染、SSR 水合等能力的前提。</p><h2 id="整体流程" tabindex="-1">整体流程 <a class="header-anchor" href="#整体流程" aria-label="Permalink to “整体流程”">​</a></h2><p>一次更新大致经历：</p><ol><li><strong>触发更新</strong>：<code>setState</code> / <code>useState</code> / props 变化等</li><li><strong>Render 阶段</strong>：根据 Fiber 树做 Diff，算出需要变更的部分（可被打断）</li><li><strong>Commit 阶段</strong>：把变更一次性应用到 DOM，并执行副作用（同步、不可打断）</li></ol><p>可以记成：<strong>Render 算差异，Commit 落盘。</strong></p><h2 id="专题目录" tabindex="-1">专题目录 <a class="header-anchor" href="#专题目录" aria-label="Permalink to “专题目录”">​</a></h2><table tabindex="0"><thead><tr><th>专题</th><th>关注点</th></tr></thead><tbody><tr><td><a href="./虚拟DOM">Virtual DOM</a></td><td>JSX / <code>createElement</code>，UI 的描述结构</td></tr><tr><td><a href="./fiber">Fiber</a></td><td>工作单元、可中断渲染的数据结构</td></tr><tr><td><a href="./协调">协调 Diff</a></td><td>新旧树如何对比、<code>key</code> 的作用</td></tr><tr><td><a href="./双阶段">Render 与 Commit</a></td><td>双阶段各自做什么、为什么要拆开</td></tr><tr><td><a href="./并发渲染">并发渲染</a></td><td>优先级调度与相关 API</td></tr><tr><td><a href="./hydrate">hydrate</a></td><td>SSR 场景下如何接管已有 HTML</td></tr></tbody></table><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><ul><li>Virtual DOM：描述 UI</li><li>Reconciliation：找出差异</li><li>Fiber：把工作拆成可调度的单元</li><li>Render / Commit：先算后写，保证更新可控</li></ul>',11)])])}const p=e(i,[["render",o]]);export{m as __pageData,p as default};
